/**
 * Migration Journal Service
 *
 * Reads the Drizzle-generated `meta/_journal.json` file to determine what
 * migrations exist in the current code. Serves as the single source of truth
 * for registration guard checks — no hand-maintained manifest needed.
 *
 * The `_journal.json` is auto-generated by `drizzle-kit generate` and tracks
 * every migration with its index, tag (filename), and breakpoints.
 *
 * Structure of _journal.json:
 * {
 *   "version": "7",
 *   "dialect": "postgresql",
 *   "entries": [
 *     { "idx": 0, "version": "7", "when": 123456, "tag": "0000_initial", "breakpoints": true },
 *     ...
 *   ]
 * }
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { Injectable, Logger } from "@nestjs/common";
import z from "zod/v4";

import { AppError } from "@deployer/errors";
import { GLOBAL_MIGRATIONS_DIR } from "@deployer/nest-schema";

/**
 * The path to the generated journal.
 *
 * ── WHY THE LOCAL PATH ARITHMETIC WAS DELETED ───────────────────────────────
 * This file used to build the path itself, as:
 *
 *   join(__dirname, "..", "..", "..", "src", "config", "drizzle", "global",
 *        "migrations", "meta", "_journal.json")
 *
 * with a comment reading "This file lives at
 * apps/api/src/core/utils/migration-journal.service.ts". Both the arithmetic and
 * the comment described a tree that no longer exists: the file moved to
 * `shared/src/core/utils/` and its target moved out of the app entirely. The
 * result was a silent `Can't find meta/_journal.json file` — a path built from
 * `import.meta.url` is only a string, so nothing checks it at compile time.
 *
 * It is now derived from the migrations directory's own resolver, which is the
 * only place that knows where the journal lives.
 */
const JOURNAL_PATH = join(GLOBAL_MIGRATIONS_DIR, "meta", "_journal.json");

// ─── Types ────────────────────────────────────────────────────────────────────

/**
 * The journal as drizzle-kit writes it. The schema IS the validator: the file is generated by another tool, so every
 * field is checked once at load instead of per-entry `typeof` checks that can drift from the type.
 */
export const journalEntrySchema = z.object({
  idx: z.number(),
  version: z.string(),
  when: z.number(),
  tag: z.string(),
  breakpoints: z.boolean(),
});

export const migrationJournalSchema = z.object({
  version: z.string(),
  dialect: z.string(),
  entries: z.array(journalEntrySchema),
});

export type JournalEntry = z.infer<typeof journalEntrySchema>;
export type MigrationJournal = z.infer<typeof migrationJournalSchema>;

// ─── Service ──────────────────────────────────────────────────────────────────

@Injectable()
export class MigrationJournalService {
  private readonly logger = new Logger(MigrationJournalService.name);
  private journal: MigrationJournal | null = null;

  /**
   * Load the journal from disk. Results are cached after first read.
   */
  load(): MigrationJournal {
    if (this.journal) return this.journal;

    try {
      const raw = readFileSync(JOURNAL_PATH, "utf-8");
      const parsed = migrationJournalSchema.safeParse(JSON.parse(raw));
      if (!parsed.success) {
        throw new AppError(`Invalid migration journal: ${parsed.error.message}`, "INTERNAL_ERROR");
      }

      this.journal = parsed.data;
      this.logger.log(
        `📖 Loaded migration journal: ${parsed.data.entries.length} migration(s), schema version ${parsed.data.version}`,
      );
      return parsed.data;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      this.logger.error(`❌ Failed to load migration journal: ${message}`);
      throw new AppError(
        `Migration journal missing or corrupted at ${JOURNAL_PATH}: ${message}`,
"INTERNAL_ERROR");
    }
  }

  /**
   * Get the list of all migration tags from the journal.
   * Tags are like "0000_brave_steve_rogers", "0011_cynical_goliath", etc.
   */
  getMigrationTags(): string[] {
    return this.load().entries.map((e) => e.tag);
  }

  /**
   * Get the latest migration tag (the highest idx).
   */
  getLatestMigrationTag(): string | null {
    const entries = this.load().entries;
    if (entries.length === 0) return null;
    const sorted = [...entries].sort((a, b) => b.idx - a.idx);
    return sorted[0]!.tag;
  }

  /**
   * Get the latest migration index.
   */
  getLatestMigrationIdx(): number {
    const entries = this.load().entries;
    if (entries.length === 0) return -1;
    return Math.max(...entries.map((e) => e.idx));
  }

  /**
   * Check if a specific migration tag exists in the journal.
   */
  hasMigration(tag: string): boolean {
    return this.load().entries.some((e) => e.tag === tag);
  }

  /**
   * Count how many migrations exist in the journal.
   */
  getMigrationCount(): number {
    return this.load().entries.length;
  }
}
